mapper.select:
SELECT distinct ac.id, ac.name, ac.sort, ac.bool_section_steel, ac.last_change_id FROM sys_assemble_config AS ac LEFT JOIN sys_assemble_spec spec on spec.assemble_config_id = ac.id and spec.bool_delete_enum = 0 WHERE ac.bool_delete_enum = 0
AND ac.name like concat('%',#{name},'%')
AND ac.bool_section_steel = #{boolSectionSteel}
and (ac.name like concat('%',#{sectionAndNameAndType},'%') or spec.spec_prefix like concat('%',#{sectionAndNameAndType},'%'))
AND ac.mes_product_enum = #{mesProductEnum}
ORDER BY ac.sort, ac.id
